initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentPeriod = 30;
  let salesChart = null;
  let weatherChart = null;

  // 店舗選択の初期化
  function initStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
      if (storeTable.records.length > 0) {
        currentStoreId = storeTable.records[0].店舗ID;
        storeSelect.value = currentStoreId;
      }
    }
  }

  // KPI計算
  function calculateKPIs(salesData, predictionData, orderData) {
    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    // 売上実績
    const filteredSales = salesData.filter(s => {
      const saleDate = new Date(s.売上日);
      return saleDate >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId);
    });

    const totalSales = filteredSales.reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    // 予測精度（MAPE計算）
    const accuracyData = predictionData.filter(p => p.実績数量 && p.予測数量);
    let avgAccuracy = 0;
    if (accuracyData.length > 0) {
      const mape = accuracyData.reduce((sum, p) => {
        const error = Math.abs(p.実績数量 - p.予測数量) / p.実績数量;
        return sum + error;
      }, 0) / accuracyData.length;
      avgAccuracy = Math.max(0, (1 - mape) * 100);
    }

    // 発注件数
    const filteredOrders = orderData.filter(o => {
      const orderDate = new Date(o.発注日);
      return orderDate >= periodStart && (!currentStoreId || o.店舗ID === currentStoreId);
    });

    // アラート件数（在庫切れフラグのある売上データから推定）
    const alertCount = filteredSales.filter(s => s.在庫切れフラグ).length;

    // UI更新
    container.querySelector('#sales-amount').textContent = `¥${totalSales.toLocaleString()}`;
    container.querySelector('#prediction-accuracy').textContent = `${avgAccuracy.toFixed(1)}%`;
    container.querySelector('#order-count').textContent = `${filteredOrders.length}件`;
    container.querySelector('#alert-count').textContent = `${alertCount}件`;
  }

  // 売上トレンドグラフ
  function renderSalesTrend(salesData) {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');

    if (salesChart) {
      salesChart.destroy();
    }

    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const filteredSales = salesData.filter(s => {
      const saleDate = new Date(s.売上日);
      return saleDate >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId);
    });

    // 日別集計
    const dailySales = {};
    filteredSales.forEach(s => {
      const dateKey = s.売上日.slice(0, 10);
      dailySales[dateKey] = (dailySales[dateKey] || 0) + s.売上金額;
    });

    const labels = Object.keys(dailySales).sort();
    const data = labels.map(date => dailySales[date]);

    salesChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function renderProductRanking(salesData, productData) {
    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const filteredSales = salesData.filter(s => {
      const saleDate = new Date(s.売上日);
      return saleDate >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId);
    });

    const productSales = {};
    filteredSales.forEach(s => {
      productSales[s.商品ID] = (productSales[s.商品ID] || 0) + s.売上金額;
    });

    const ranking = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    const rankingHtml = ranking.map(([productId, amount], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product ? product.商品名 : '不明な商品';
      return `
        <div class="ranking-item">
          <span class="rank">${index + 1}</span>
          <span class="product-name">${productName}</span>
          <span class="amount">¥${amount.toLocaleString()}</span>
        </div>
      `;
    }).join('');

    container.querySelector('#product-ranking').innerHTML = rankingHtml || '<div class="ranking-item"><span class="product-name">データがありません</span></div>';
  }

  // 天候影響分析チャート
  function renderWeatherChart(salesData, weatherData) {
    const ctx = container.querySelector('#weather-chart').getContext('2d');

    if (weatherChart) {
      weatherChart.destroy();
    }

    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const dailySales = {};
    const dailyWeather = {};

    salesData.forEach(s => {
      const dateKey = s.売上日.slice(0, 10);
      if (new Date(dateKey) >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId)) {
        dailySales[dateKey] = (dailySales[dateKey] || 0) + s.売上金額;
      }
    });

    weatherData.forEach(w => {
      const dateKey = w.観測日.slice(0, 10);
      if (new Date(dateKey) >= periodStart && (!currentStoreId || w.店舗ID === currentStoreId)) {
        dailyWeather[dateKey] = w.平均気温;
      }
    });

    const labels = Object.keys(dailySales).sort();
    const salesValues = labels.map(date => dailySales[date] || 0);
    const tempValues = labels.map(date => dailyWeather[date] || 0);

    weatherChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: salesValues,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          yAxisID: 'y'
        }, {
          label: '平均気温',
          data: tempValues,
          borderColor: '#ff6a00',
          backgroundColor: 'rgba(255, 106, 0, 0.1)',
          yAxisID: 'y1'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            type: 'linear',
            display: true,
            position: 'left',
          },
          y1: {
            type: 'linear',
            display: true,
            position: 'right',
            grid: {
              drawOnChartArea: false,
            },
          }
        }
      }
    });
  }

  // 発注状況更新
  function updateOrderStatus(orderData) {
    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const filteredOrders = orderData.filter(o => {
      const orderDate = new Date(o.発注日);
      return orderDate >= periodStart && (!currentStoreId || o.店舗ID === currentStoreId);
    });

    const pending = filteredOrders.filter(o => o.発注ステータス === '未発注').length;
    const ordered = filteredOrders.filter(o => o.発注ステータス === '発注済').length;
    const received = filteredOrders.filter(o => o.発注ステータス === '納品済').length;

    container.querySelector('#pending-orders').textContent = pending;
    container.querySelector('#ordered-items').textContent = ordered;
    container.querySelector('#received-items').textContent = received;
  }

  // イベント・季節要因表示
  function renderEventFactors(eventData, seasonData) {
    const now = new Date();
    const futureDate = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

    const upcomingEvents = eventData.filter(e => {
      const startDate = new Date(e.開始日時);
      return startDate >= now && startDate <= futureDate && (!currentStoreId || e.店舗ID === currentStoreId);
    }).slice(0, 5);

    const eventHtml = upcomingEvents.map(e => `
      <div class="event-item">
        <span class="event-type">${e.イベント名}</span>
        <span class="event-impact">${e.影響度}</span>
      </div>
    `).join('');

    container.querySelector('#event-factors').innerHTML = eventHtml || '<div class="event-item"><span class="event-type">予定されたイベントはありません</span></div>';
  }

  // 在庫アラート表示
  function renderInventoryAlerts(salesData, productData) {
    const alerts = salesData.filter(s => s.在庫切れフラグ && (!currentStoreId || s.店舗ID === currentStoreId))
      .slice(0, 10);

    const alertHtml = alerts.map(s => {
      const product = productData.find(p => p.商品ID === s.商品ID);
      const productName = product ? product.商品名 : '不明な商品';
      return `
        <div class="alert-item">
          <span class="alert-product">${productName}</span>
          <span class="alert-level warning">警告</span>
        </div>
      `;
    }).join('');

    container.querySelector('#inventory-alerts').innerHTML = alertHtml || '<div class="alert-item"><span class="alert-product">アラートはありません</span></div>';
  }

  // データ更新
  async function updateDashboard() {
    try {
      const [salesData, productData, predictionData, orderData, weatherData, eventData, seasonData] = await Promise.all([
        window.aivicApi.list(3), // 売上実績データ
        window.aivicApi.list(2), // 商品マスタ
        window.aivicApi.list(8), // 需要予測結果
        window.aivicApi.list(9), // 発注データ
        window.aivicApi.list(4), // 天候データ
        window.aivicApi.list(5), // イベントデータ
        window.aivicApi.list(6)  // 季節情報データ
      ]);

      if (salesData && productData && predictionData && orderData) {
        calculateKPIs(salesData, predictionData, orderData);
        renderSalesTrend(salesData);
        renderProductRanking(salesData, productData);
        updateOrderStatus(orderData);
        renderInventoryAlerts(salesData, productData);

        if (weatherData) {
          renderWeatherChart(salesData, weatherData);
        }

        if (eventData && seasonData) {
          renderEventFactors(eventData, seasonData);
        }
      }
    } catch (error) {
      console.error('ダッシュボードデータの更新に失敗しました:', error);
      container.insertAdjacentHTML('afterbegin', '<div class="error-message">データの取得に失敗しました。ページを再読み込みしてください。</div>');
    }
  }

  // イベントリスナー
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateDashboard();
  });

  container.querySelector('#period-select').addEventListener('change', (e) => {
    currentPeriod = parseInt(e.target.value);
    updateDashboard();
  });

  // 初期化
  initStoreSelect();
  updateDashboard();
}
